import{_ as n,a0 as l,w as p,s as h,ao as u,I as r,x as e,a1 as i,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const W=JSON.parse('{"title":"如何在 Ubuntu 22.04 中安裝和使用 Wireshark | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 中安裝和使用 Wireshark | LCTT (202307) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 中安裝和使用 Wireshark | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 中安裝和使用 Wireshark | LCTT (202307) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04","title":"如何在 Ubuntu 22.04 中安裝和使用 Wireshark","tag":"202307","desc":""},"relativePath":"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04.md","filePath":"[post].md"}'),o={name:"202307/20230624.0 ⭐️⭐️ How to Install and Use Wireshark in Ubuntu 22.04.md"};function d(k,s,c,b,g,w){const a=l("Link");return p(),h("div",null,[s[15]||(s[15]=u(`<h1 id="如何在-ubuntu-22-04-中安裝和使用-wireshark" tabindex="-1">如何在 Ubuntu 22.04 中安裝和使用 Wireshark <a class="header-anchor" href="#如何在-ubuntu-22-04-中安裝和使用-wireshark" aria-label="Permalink to “如何在 Ubuntu 22.04 中安裝和使用 Wireshark”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202307/05/154817pj3jx0jl03levzu9.jpg" alt=""></p><blockquote><p>技術兄弟們，大家好，在這篇文章中我們將介紹如何在 Ubuntu 22.04 中安裝和使用 Wireshark。</p></blockquote><p>Wireshark 是自由開源的、跨平台的、基於 GUI 的網絡數據包分析器，可用於 Linux、Windows、MacOS、Solaris 等。它實時捕獲網絡數據包並以人類可讀的格式呈現它們。它使我們能夠監控微觀層面的網絡數據包。它還有一個名為 <code>tshark</code> 的命令列程序，它執行與 Wireshark 相同的功能，但通過終端而不是通過 GUI。</p><p>Wireshark 可用於網絡故障排除、分析、軟件和通信協議開發，也可用於教育目的。Wireshark 使用名為 <code>pcap</code> 的庫來捕獲網絡數據包。</p><h3 id="wireshark-的功能" tabindex="-1">Wireshark 的功能 <a class="header-anchor" href="#wireshark-的功能" aria-label="Permalink to “Wireshark 的功能”">​</a></h3><ul><li>支持檢查數百種協議</li><li>能夠實時捕獲數據包並保存它們以供以後離線分析</li><li>一些用於分析數據的過濾器</li><li>捕獲的數據可以動態壓縮和解壓縮</li><li>支持多種數據分析文件格式，輸出也可以保存為 XML、CSV、純文本格式</li><li>可以從以太網、WiFi、藍牙、USB、幀中繼、令牌環等多種接口捕獲數據</li></ul><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><ul><li>預裝 Ubuntu 22.04</li><li>具有 sudo 權限的本地用户</li><li>互聯網連接</li></ul><h3 id="wireshark-安裝步驟" tabindex="-1">Wireshark 安裝步驟 <a class="header-anchor" href="#wireshark-安裝步驟" aria-label="Permalink to “Wireshark 安裝步驟”">​</a></h3><h4 id="從-ubuntu-倉庫安裝" tabindex="-1">從 Ubuntu 倉庫安裝 <a class="header-anchor" href="#從-ubuntu-倉庫安裝" aria-label="Permalink to “從 Ubuntu 倉庫安裝”">​</a></h4><p>Wireshark 包可在默認的 Ubuntu 倉庫中找到，並且可以使用以下命令簡單地安裝。但你可能無法獲得最新版本的 wireshark。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt update</span></span>
<span class="line"><span>$ sudo apt install wireshark</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Apt-Command-Install-Wireshark-Ubuntu.png" alt="Apt-Command-Install-Wireshark-Ubuntu"></p><p>選擇 “Yes” 允許非超級用户使用 Wireshark 捕獲數據包：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Allow-Non-SuperUsers-To-Capture-Packets-Wireshark-Ubuntu.png" alt="Allow-Non-SuperUsers-To-Capture-Packets-Wireshark-Ubuntu"></p><p>安裝成功後，訪問 Wireshare UI。從“<ruby>活動<rt>Activities</rt></ruby>”中搜索 “wireshark”，然後單擊其圖標。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Wireshark-UI-Ubuntu-Linux-Desktop.png" alt="Wireshark-UI-Ubuntu-Linux-Desktop"></p><p>以上確認你的 Wireshark 安裝已成功完成。</p><h4 id="安裝最新的版本" tabindex="-1">安裝最新的版本 <a class="header-anchor" href="#安裝最新的版本" aria-label="Permalink to “安裝最新的版本”">​</a></h4><p>如果要安裝最新版本的 Wireshark，我們必須使用以下 <code>apt</code> 命令啓用官方 Wireshark 倉庫：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo add-apt-repository ppa:wireshark-dev/stable</span></span>
<span class="line"><span>$ sudo apt update</span></span></code></pre></div><p>現在，安裝最新版本的 Wireshark，運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install wireshark -y</span></span></code></pre></div><p>安裝 Wireshark 後，驗證其版本：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ wireshark --version</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Wireshark-Version-Check-Ubuntu-Linux.png" alt="Wireshark-Version-Check-Ubuntu-Linux"></p><p>要允許普通用户使用 Wireshark 使用和捕獲數據包，請運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dpkg-reconfigure wireshark-common</span></span></code></pre></div><p>選擇 “Yes” 並按回車鍵。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Allow-Regular-User-Use-Wireshark-Ubuntu.png" alt="Allow-Regular-User-Use-Wireshark-Ubuntu"></p><p>使用 <code>usermod</code> 命令將本地用户添加到 <code>wireshark</code> 組:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo usermod -aG wireshark $USER</span></span>
<span class="line"><span>$ newgrp wireshark</span></span></code></pre></div><p>要使上述更改生效，請重新啓動系統。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo reboot</span></span></code></pre></div><h3 id="使用-wireshark-捕獲數據包" tabindex="-1">使用 Wireshark 捕獲數據包 <a class="header-anchor" href="#使用-wireshark-捕獲數據包" aria-label="Permalink to “使用 Wireshark 捕獲數據包”">​</a></h3><p>啓動 Wireshark，從“活動”-&gt;搜索 “wireshark”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Access-Wireshark-Ubuntu-Desktop.png" alt="Access-Wireshark-Ubuntu-Desktop"></p><p>單擊 Wireshark 圖標，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Choose-Interface-Wireshark-UI-Ubuntu.png" alt="Choose-Interface-Wireshark-UI-Ubuntu"></p><p>所有這些都是我們可以捕獲網絡數據包的接口。根據你係統上的界面，此頁面可能會有所不同。</p><p>我們選擇 “enp0s3” 來捕獲該接口的網絡流量。選擇接口後，我們網絡上所有設備的網絡數據包開始填充（請參閲下面的截圖）：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Capturing-Packets-WireShark-UI-Ubuntu.png" alt="Capturing-Packets-WireShark-UI-Ubuntu"></p><p>第一次看到此頁面時，我們可能會被此屏幕中顯示的數據淹沒，並且可能會想到如何整理這些數據，但不用擔心，Wireshark 的最佳功能之一就是它的過濾器。</p><p>我們可以根據 IP 地址、端口號對數據進行排序/過濾，還可以使用源和目標過濾器、數據包大小等，還可以將 2 個或更多過濾器組合在一起以創建更全面的搜索。我們可以在“<ruby>應用顯示過濾器<rt>Apply a Display Filter</rt></ruby>”選項卡中編寫過濾器，也可以選擇已創建的規則之一。要選擇預建過濾器，請單擊“旗幟”圖標，然後點擊“應用顯示過濾器”選項卡。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/IP-Based-Filtering-WireShark-UI-Ubuntu.png" alt="IP-Based-Filtering-WireShark-UI-Ubuntu"></p><p>我們還可以根據顏色代碼來過濾數據，默認情況下，淺紫色是 TCP 流量，淺藍色是 UDP 流量，黑色標識有錯誤的數據包，要查看這些代碼的含義，請單擊“<ruby>查看<rt>View</rt></ruby>”-&gt;“<ruby>顏色規則<rt>Coloring Rules</rt></ruby>”，我們也可以更改這些代碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Coloring-Rules-WireShark-Ubuntu.png" alt="Coloring-Rules-WireShark-Ubuntu"></p><p>獲得所需的結果後，我們可以單擊任何捕獲的數據包以獲取有關該數據包的更多詳細信息，這將顯示有關該網絡數據包的所有數據。</p><p>要停止捕獲數據包，請單擊紅色停止按鈕，然後將捕獲的數據包保存到文件中。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2017/11/Save-Captured-Packets-Wireshark-Ubuntu.png" alt="Save-Captured-Packets-Wireshark-Ubuntu"></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>Wireshark 是一款非常強大的工具，需要一些時間來適應和掌握它，這篇文章將幫助你開始使用。請隨時在下面的評論欄中提出你的疑問或建議。</p><p><em>（題圖：MJ/63c09e75-a3e7-4dbf-ac6f-0233bdd34ad8）</em></p><hr>`,55)),r("p",null,[s[1]||(s[1]=e("via: ",-1)),i(a,{href:"https://www.linuxtechi.com/install-use-wireshark-ubuntu/"},{default:t(()=>[...s[0]||(s[0]=[e("https://www.linuxtechi.com/install-use-wireshark-ubuntu/",-1)])]),_:1})]),r("p",null,[s[6]||(s[6]=e("作者：",-1)),i(a,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:t(()=>[...s[2]||(s[2]=[e("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),i(a,{href:"https://github.com/lkxed/"},{default:t(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:t(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),r("p",null,[s[12]||(s[12]=e("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const f=n(o,[["render",d]]);export{W as __pageData,f as default};
